window.RP_SESSION={"id":"S-cdf981d52895","messages":[{"id":"RP-III-0068793","time":"2026-04-11T01:23:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"이 길드에 처음 왔을 때, 등록도 안 하고 길드 회관에서 만난 사람들과 술부터 마시러 갔었지.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068794","time":"2026-04-11T01:24:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그것도 몇 달은 된 일인데, 여기 사람들과 쌓은 다른 추억들이 너무 많아서 마치 몇 년은 된 것 처럼 느껴진다.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068795","time":"2026-04-11T01:25:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"많은 인연들이 새로 생기고, 사라지고, 변화하고.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068796","time":"2026-04-11T01:25:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그 때 함께 있던 많은 사람들이 지금은 없고, 없던 많은 사람들이 지금은 함께 있구나.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068797","time":"2026-04-11T01:27:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그들과 처음 갔던 술집. 마리아, 베레디르, 그리고...","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068798","time":"2026-04-11T01:27:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"뭐, 어쨌건.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068799","time":"2026-04-11T01:28:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"엘타리온은 그 술집으로 들어가 혼자 앉는다. 지금은 그녀에게 돈이 생겼다. 처음 왔을 때 뭐가 제일 맛있었더라?","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068800","time":"2026-04-11T01:28:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그래, 분명 향신료가 잔뜩 쳐진 오리 요리와, 도수가 높은 독한 종류의 고농축 맥주였지.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068801","time":"2026-04-11T01:29:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"주문을 하고 잠시 기다리니 오리 요리와 맥주 열 잔이 나온다. 엘타리온은 고기를 뜯고 맥주를 마시기 시작한다.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068802","time":"2026-04-11T01:30:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"총 6실버. 지금의 엘타리온에게는 어느 정도 부담이 되어도 이 맛을 위해 충분히 낼 수 있는 금액인 반면. 그 때의 그녀였다면 꿈도 꾸지 못했을 가격.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068803","time":"2026-04-11T01:31:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"식사를 마친 엘타리온은 은화 여섯 개를 종업원에게 건내고, 팁으로 하나를 더 건낸다. 종업원이 꾸벅 감사 인사를 한다.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068804","time":"2026-04-11T01:33:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"고도수 맥주 열 잔. 그 때는 술을 마시는 법을 제대로 몰라서 겨우 이걸 마시고 만취했었지.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068805","time":"2026-04-11T01:33:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"덕분에 레드엘프라는 별명도 붙고...","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068806","time":"2026-04-11T01:34:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"길드로 돌아가기 위해 길을 걷다가 익숙한 뒷골목이 보인다. 뭐더라?","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068807","time":"2026-04-11T01:35:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"아, 어떤 더러운 남자에게서 자그마한 바드 소년을 구해줬던 거리.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068808","time":"2026-04-11T01:35:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"캐너리 군은 뭘 하고 지내려나. 아니, 살아는 있을까.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068809","time":"2026-04-11T01:36:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"캐너리가 돌아오지 않던 날 밤 린과 함께 캐너리의 흔적을 찾아가 봤지만 수 차례 폭력의 흔적 이후 누군가에게 끌려간 듯 개울을 건너가며 흔적이 끊겨서 더는 추적하지 못했던 기억이 떠오를 때 쯤.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068810","time":"2026-04-11T01:36:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"이상하리만치 취한 몸을 이끌고 길드 건물에 도착했다.","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068811","time":"2026-04-11T01:42:00+09:00","room":"RP III","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-cf2651679b0b"]},{"id":"RP-III-0068812","time":"2026-04-11T01:42:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
